<?php
namespace App\Http\Controllers;
use App\Models\Volunteer; use App\Models\VolunteerHour; use Illuminate\Http\Request;
class VolunteerPortalController extends Controller { public function index(){ $volunteer=Volunteer::where('user_id',auth()->id())->first(); if(!$volunteer)return redirect()->route('volunteer.apply'); $hours=VolunteerHour::where('volunteer_id',$volunteer->id)->latest('started_at')->paginate(15); $total=VolunteerHour::where('volunteer_id',$volunteer->id)->sum('hours'); return view('volunteer.dashboard',compact('volunteer','hours','total')); } public function apply(){return view('volunteer.apply');} public function storeApplication(Request $request){$data=$request->validate(['phone'=>'nullable|string|max:50','skills'=>'nullable|string|max:2000','experience'=>'nullable|string|max:5000','availability'=>'nullable|string|max:1000','emergency_contact'=>'nullable|string|max:255']); if(Volunteer::where('user_id',auth()->id())->exists())return redirect()->route('volunteer.dashboard'); Volunteer::create(array_merge($data,['user_id'=>auth()->id(),'name'=>auth()->user()->name,'email'=>auth()->user()->email,'status'=>'pending'])); return redirect()->route('volunteer.dashboard')->with('success','Volunteer application submitted for review.');} public function checkIn(){ $v=Volunteer::where('user_id',auth()->id())->where('status','approved')->firstOrFail(); if(VolunteerHour::where('volunteer_id',$v->id)->whereNull('ended_at')->exists())return back()->with('success','You already have an active session.'); VolunteerHour::create(['volunteer_id'=>$v->id,'activity'=>'Volunteer session','started_at'=>now()]); return back()->with('success','Checked in successfully.'); } public function checkOut(VolunteerHour $hour){abort_unless($hour->volunteer->user_id===auth()->id() && !$hour->ended_at,403);$hour->ended_at=now();$hour->hours=round($hour->started_at->diffInMinutes($hour->ended_at)/60,2);$hour->save();return back()->with('success','Checked out successfully.');} }
